// Cat Client — XHTTP relay for Vercel (Edge runtime). Generated by the Cat Client app.
// It forwards ONLY requests under the configured XHTTP path to your own Xray server and streams
// the answer back unchanged. Every other path gets a small static page, so the project is not an
// open proxy. Edge cannot skip TLS checks, so the server needs a valid certificate for UP.host.
// Licence: GPL-3.0 (Cat Client).
export const config = { runtime: 'edge', regions: /*CAT_REGIONS*/["fra1"]/*END*/ };

const UP = /*CAT_UPSTREAM*/{"proto":"https","connect":"example.com","port":443,"servername":"example.com","host":"example.com","insecure":false,"path":"/"}/*END*/;

const DROP_REQ = new Set(['host', 'connection', 'keep-alive', 'proxy-connection', 'proxy-authorization',
  'te', 'trailer', 'transfer-encoding', 'upgrade', 'forwarded', 'x-real-ip', 'x-forwarded-for',
  'x-forwarded-host', 'x-forwarded-proto', 'x-forwarded-port', 'accept-encoding', 'content-length']);
const DROP_RES = new Set(['connection', 'keep-alive', 'transfer-encoding', 'content-encoding', 'content-length']);

function guarded(pathAndQuery) {
  const base = UP.path.endsWith('/') ? UP.path.slice(0, -1) : UP.path;
  if (!base) return true;
  return pathAndQuery === base || pathAndQuery.startsWith(base + '/') || pathAndQuery.startsWith(base + '?');
}

export default async function handler(req) {
  const u = new URL(req.url);
  const pathAndQuery = u.pathname + u.search;
  if (!guarded(pathAndQuery)) {
    return new Response('<!doctype html><title>Notes</title><p>Nothing to see here.</p>', {
      headers: { 'content-type': 'text/html; charset=utf-8', 'cache-control': 'public, max-age=3600' },
    });
  }
  const headers = new Headers();
  for (const [k, v] of req.headers) {
    const key = k.toLowerCase();
    if (DROP_REQ.has(key) || key.startsWith('x-vercel-')) continue;
    headers.set(key, v);
  }
  const defaultPort = UP.proto === 'https' ? 443 : 80;
  const origin = UP.proto + '://' + UP.host + (UP.port === defaultPort ? '' : ':' + UP.port);
  const method = req.method.toUpperCase();
  const init = { method, headers, redirect: 'manual' };
  if (method !== 'GET' && method !== 'HEAD') {
    init.body = req.body;
    init.duplex = 'half';
  }
  try {
    const up = await fetch(origin + pathAndQuery, init);
    const out = new Headers();
    for (const [k, v] of up.headers) if (!DROP_RES.has(k.toLowerCase())) out.set(k, v);
    out.set('x-accel-buffering', 'no');
    out.set('cache-control', 'no-store');
    return new Response(up.body, { status: up.status, headers: out });
  } catch (e) {
    return new Response('upstream unreachable', { status: 502 });
  }
}
